"""Set a project up and keep its generated files current.

auto() is the entry point every trigger calls (session start, each prompt, cd,
git hooks). It returns in a few milliseconds when nothing changed. It only ever
writes inside marked blocks, .harness/, and what fieldbook itself creates, and
it never raises: a failed trigger must not break a shell, a commit or a session.
"""
from __future__ import annotations

import hashlib
import json
import os
import shutil
import subprocess
import time
from pathlib import Path

from . import BASE, DATA, ENGINE_VERSION, SHARED, decide, project, tokens

BEGIN = "<!-- BEGIN ai-dotfiles:harness -->"
END = "<!-- END ai-dotfiles:harness -->"
IMPORT_BEGIN = "<!-- BEGIN ai-dotfiles:import -->"
IMPORT_END = "<!-- END ai-dotfiles:import -->"
LOCK_STALE_SECONDS = 180


def _load(path, default):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return default


def _state_path(root):
    return DATA / "projects" / (hashlib.sha1(str(root).encode()).hexdigest()[:16] + ".json")


def _read(path):
    try:
        return Path(path).read_text(encoding="utf-8")
    except OSError:
        return None


def upsert_block(path, begin, end, body, header=""):
    """Replace the marked block, or append it. Text outside the markers is never touched."""
    text = _read(path)
    existed = text is not None
    text = header if text is None else text
    block = "%s\n%s\n%s" % (begin, body.strip(), end)
    if begin in text and end in text:
        head, rest = text.split(begin, 1)
        new = head + block + rest.split(end, 1)[1]
    else:
        sep = "" if not text or text.endswith("\n\n") else ("\n" if text.endswith("\n") else "\n\n")
        new = text + sep + block + "\n"
    if existed and new == text:
        return "kept"
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(new, encoding="utf-8")
    return "updated" if existed else "created"


def remove_block(path, begin, end):
    text = _read(path)
    if text is None or begin not in text or end not in text:
        return False
    head, rest = text.split(begin, 1)
    new = (head.rstrip("\n") + "\n" + rest.split(end, 1)[1].lstrip("\n")).strip("\n")
    if new.strip():
        Path(path).write_text(new + "\n", encoding="utf-8")
    else:
        os.remove(path)
    return True


def build_block(tags, commands, pm, has_fieldbook):
    """The generated AGENTS.md block, trimmed to the project_block token cap."""
    cfg = _load(BASE / "config" / "project-rules.json", {})
    cap = _load(BASE / "config" / "harness-budgets.json", {}).get("project_block", 600)
    dos = list(cfg.get("universal", {}).get("do", []))
    donts = list(cfg.get("universal", {}).get("dont", []))
    extra_do, extra_dont = [], []
    for tag in tags:
        extra_do += cfg.get("tags", {}).get(tag, {}).get("do", [])
        extra_dont += cfg.get("tags", {}).get(tag, {}).get("dont", [])
    domains = ["security", "testing"] + [t for t in ("nodejs", "python", "java", "kotlin") if t in tags
                                         or (t == "nodejs" and {"javascript", "typescript", "react"} & set(tags))]
    domains = list(dict.fromkeys(domains))

    def render(extra_do, extra_dont):
        lines = ["## Project harness", "",
                 "Generated by ai-dotfiles from this project's files and rewritten when they change.",
                 "Write your own rules outside this block.", ""]
        if tags:
            lines.append("Stack: %s%s" % (", ".join(tags), " (%s)" % pm if pm else ""))
        else:
            lines.append("Stack: not detected yet. This block fills in when a manifest appears.")
        lines.append("")
        if commands:
            lines.append("Commands:")
            lines += ["- %s: `%s`" % (k, v) for k, v in commands.items()]
        else:
            lines.append("Commands: none defined in the project files yet.")
        lines += ["", "Do:"] + ["- " + x for x in dos + extra_do]
        lines += ["", "Don't:"] + ["- " + x for x in donts + extra_dont]
        lines += ["", "Before a change, read the domain rules that match it: "
                  + ", ".join("~/.ai-rules/rules/domains/%s.md" % d for d in domains) + ".",
                  "Base rules are the machine-wide rules your tool already loads. If it loaded none, read ~/.ai-rules/RULES.md. This file wins on conflict."]
        if has_fieldbook:
            lines.append("Decisions: check .fieldbook/bank/04-decisions.md before contradicting one, and record a new one there when a choice will still matter later.")
        else:
            lines.append("Decisions: check .harness/decisions.md before contradicting one, and add a dated line there (decision, reason, what was rejected) when a choice will still matter later.")
        lines.append("Setup changes made by the engine are logged in .harness/CHANGELOG.md.")
        return "\n".join(lines)

    text = render(extra_do, extra_dont)
    while tokens(text) > cap and (extra_do or extra_dont):
        if len(extra_dont) >= len(extra_do):
            extra_dont.pop()
        else:
            extra_do.pop()
        text = render(extra_do, extra_dont)
    return text


def _changelog(root, line):
    path = root / ".harness" / "CHANGELOG.md"
    path.parent.mkdir(exist_ok=True)
    if not path.exists():
        path.write_text("# Harness changelog\n\nSetup and updates made automatically by the ai-dotfiles engine. Newest last.\n\n", encoding="utf-8")
    with open(path, "a", encoding="utf-8") as fh:
        fh.write("- %s %s\n" % (time.strftime("%Y-%m-%d"), line))


def find_fieldbook():
    for c in (os.environ.get("FIELDBOOK_CMD"), str(Path.home() / ".fieldbook" / "bin" / "fieldbook"), shutil.which("fieldbook")):
        if c and os.path.isfile(c) and os.path.getsize(c) > 0 and os.access(c, os.X_OK):
            return c
    return None


def _run_fieldbook(root, timeout):
    fb = find_fieldbook()
    if not fb:
        return "fieldbook binary not found; no project memory created"
    try:
        r = subprocess.run([fb, "init", "--yes"], cwd=str(root), capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return "fieldbook init timed out; it is retried on the next trigger"
    except OSError as exc:
        return "fieldbook init failed to start: %s" % exc
    if r.returncode != 0:
        return "fieldbook init exited %d" % r.returncode
    return "fieldbook memory and logs initialized"


def _carry_decisions(root):
    """Move decisions recorded before git existed into the fieldbook bank."""
    src, dst = root / ".harness" / "decisions.md", root / ".fieldbook" / "bank" / "04-decisions.md"
    text = _read(src)
    if text is None or not dst.exists():
        return False
    entries = [l for l in text.splitlines() if l.startswith("- ")]
    if entries:
        with open(dst, "a", encoding="utf-8") as fh:
            fh.write("\n## Recorded before fieldbook was set up\n\n" + "\n".join(entries) + "\n")
    os.remove(src)
    return bool(entries)


def _lock(root):
    path = DATA / "locks" / hashlib.sha1(str(root).encode()).hexdigest()[:16]
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.mkdir(path)
    except FileExistsError:
        try:
            if time.time() - os.path.getmtime(path) < LOCK_STALE_SECONDS:
                return None
        except OSError:
            return None
    return path


def setup(root, trigger="manual", force=False):
    """Generate or refresh one project. Returns a result dict."""
    result = {"root": str(root), "action": "current", "notes": []}
    state_path = _state_path(root)
    state = _load(state_path, {})
    stamp = "%d|%s" % (ENGINE_VERSION, project.stamp(root))
    agents_md = root / "AGENTS.md"
    block_present = BEGIN in (_read(agents_md) or "")
    if not force and state.get("stamp") == stamp and (block_present or state.get("declined")):
        result["action"] = "current" if block_present else "declined"
        return result

    if state.get("setup") and not block_present and not force:
        # The block was deleted by hand. Treat that as a no and stay out until asked.
        if not state.get("removed"):
            if state.get("decision"):
                decide.record_outcome(state["decision"], False)
            _save_state(state_path, dict(state, removed=True, stamp=stamp))
        result["action"] = "removed-by-user"
        return result

    lock = _lock(root)
    if lock is None:
        result["action"] = "busy"
        return result
    try:
        has_git = (root / ".git").exists()
        if not state.get("setup") and not block_present and not force:
            shape = project.shape(root)
            d = decide.decide("is_project", {
                "has_git": int(has_git),
                "has_manifest": int(project.has_manifest(root)),
                "code_files": min(shape["code_files"], 5) / 5.0,
                "has_src": int(shape["has_src"]),
                "session_trigger": int(trigger in ("session", "prompt")),
            }, ctx={"root": str(root), "trigger": trigger})
            if d["answer"] is not True:
                _save_state(state_path, {"stamp": stamp, "declined": True, "decision": d["id"]})
                result["action"] = "declined"
                result["notes"].append("not treated as a project yet (p=%.2f)" % d["p"])
                return result
            state["decision"] = d["id"]

        if has_git and not (root / ".fieldbook" / "config.yml").exists():
            result["notes"].append(_run_fieldbook(root, 20 if trigger in ("session", "prompt") else 90))
        has_fieldbook = (root / ".fieldbook" / "bank").is_dir()
        if has_fieldbook and _carry_decisions(root):
            result["notes"].append("earlier decisions moved into .fieldbook/bank/04-decisions.md")

        tags = project.detect_tags(root)
        commands = project.detect_commands(root)
        block = build_block(tags, commands, project.package_manager(root), has_fieldbook)
        action = upsert_block(agents_md, BEGIN, END, block, header=HEADER)

        claude_md = root / "CLAUDE.md"
        existing = _read(claude_md)
        if existing is None or (IMPORT_BEGIN in existing) or "AGENTS.md" not in existing:
            upsert_block(claude_md, IMPORT_BEGIN, IMPORT_END, "@AGENTS.md")
        if not has_fieldbook:
            decisions = root / ".harness" / "decisions.md"
            if not decisions.exists():
                decisions.parent.mkdir(exist_ok=True)
                decisions.write_text("# Decisions\n\nOne dated line per decision: what was decided, why, and what was rejected.\n\n", encoding="utf-8")

        first = not state.get("setup")
        if first:
            line = "setup: stack %s; commands %s" % (", ".join(tags) or "none yet", ", ".join(commands) or "none yet")
        else:
            old_tags, old_cmds = set(state.get("tags", [])), state.get("commands", {})
            diffs = []
            if set(tags) != old_tags:
                diffs.append("stack %s" % " ".join(["+" + t for t in sorted(set(tags) - old_tags)] + ["-" + t for t in sorted(old_tags - set(tags))]))
            if commands != old_cmds:
                diffs.append("commands now %s" % (", ".join(commands) or "none"))
            line = "update: " + ("; ".join(diffs) if diffs else "block regenerated")
        if first or action != "kept" or result["notes"]:
            _changelog(root, line + "".join("; " + n for n in result["notes"]))
            result["action"] = "setup" if first else "updated"
        result["block"] = block
        _save_state(state_path, {"setup": True, "stamp": "%d|%s" % (ENGINE_VERSION, project.stamp(root)),
                                 "root": str(root), "tags": tags, "commands": commands,
                                 "set_up_at": state.get("set_up_at") or int(time.time()),
                                 "decision": state.get("decision")})
        return result
    finally:
        try:
            os.rmdir(lock)
        except OSError:
            pass


def _save_state(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = "%s.%d.tmp" % (path, os.getpid())
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh)
    os.replace(tmp, path)


def auto(cwd, trigger):
    """Trigger entry point. Never raises."""
    try:
        if (SHARED / "harness.off").exists() or os.environ.get("AI_HARNESS_OFF") == "1":
            return {"action": "off"}
        root, why = project.locate(cwd)
        if root is None:
            return {"action": "skip", "why": why}
        if project.is_excluded(root, project.load_excludes(SHARED / "harness-exclude")):
            return {"action": "skip", "why": "excluded", "root": str(root)}
        return setup(root, trigger)
    except Exception as exc:  # a trigger must never break its caller
        return {"action": "error", "why": "%s: %s" % (type(exc).__name__, exc)}


HEADER = "# Agent rules\n\nInstructions for any AI agent working in this repository.\n\n"


def remove(root):
    """Undo what the engine wrote. Fieldbook's store and hooks are left alone."""
    done = []
    if remove_block(root / "AGENTS.md", BEGIN, END):
        done.append("AGENTS.md block")
        if (_read(root / "AGENTS.md") or "").strip() == HEADER.strip():
            os.remove(root / "AGENTS.md")
    if remove_block(root / "CLAUDE.md", IMPORT_BEGIN, IMPORT_END):
        done.append("CLAUDE.md import")
    if (root / ".harness").is_dir():
        shutil.rmtree(root / ".harness")
        done.append(".harness/")
    try:
        os.remove(_state_path(root))
    except OSError:
        pass
    (root / ".harness-skip").write_text("Created by harness remove. Delete this file to let the engine set this project up again.\n", encoding="utf-8")
    done.append(".harness-skip written")
    return done
